choose.when:
IN (
  SELECT ca.descendant_concept_id
    FROM __PLOT_VOCAB_CONCEPT_ANCESTOR__ ca
    JOIN __PLOT_VOCAB_CONCEPT__ c_std
      ON c_std.concept_id = ca.descendant_concept_id
     AND c_std.standard_concept = 'S'
     AND c_std.domain_id = #{domainId}
   WHERE ca.ancestor_concept_id = #{conceptId}
     AND ca.min_levels_of_separation >= #{minLevels}
  UNION ALL
  SELECT #{conceptId}
)
